229	static void card_click_cb(lv_event_t *e)
230	{
231	  int idx = (int)(intptr_t)lv_event_get_user_data(e);
232	
233	  if (idx < 0 || idx >= NUM_CATEGORIES)
234	    {
235	      return;
236	    }
237	
238	  category_t *cat = &g_phy.categories[idx];
239	
240	  if (cat->expanded)
241	    {
242	      /* Collapse */
243	
244	      if (cat->detail_panel)
245	        {
246	          lv_obj_add_flag(cat->detail_panel, LV_OBJ_FLAG_HIDDEN);
247	          lv_obj_set_height(cat->card, 72);
248	        }
249	
250	      cat->expanded = false;
251	      g_phy.current_expanded = -1;
252	    }
253	  else
254	    {
255	      /* Collapse any previously expanded */
256	
257	      if (g_phy.current_expanded >= 0 &&
258	          g_phy.current_expanded < NUM_CATEGORIES)
259	        {
260	          category_t *prev =
261	            &g_phy.categories[g_phy.current_expanded];
262	          if (prev->detail_panel)
263	            {
264	              lv_obj_add_flag(prev->detail_panel, LV_OBJ_FLAG_HIDDEN);
265	              lv_obj_set_height(prev->card, 72);
266	            }
267	
268	          prev->expanded = false;
269	        }
270	
271	      /* Expand this one */
272	
273	      if (cat->detail_panel)
274	        {
275	          lv_obj_remove_flag(cat->detail_panel, LV_OBJ_FLAG_HIDDEN);
276	          int detail_h = 8 + cat->num_experiments * 36 + 8;
277	          lv_obj_set_height(cat->card, 72 + detail_h);
278	        }
279	
280	      cat->expanded = true;
281	      g_phy.current_expanded = idx;
282	    }
283	}
