285	static void experiment_click_cb(lv_event_t *e)
286	{
287	  int cat_idx = (int)(intptr_t)lv_event_get_user_data(e);
288	  lv_obj_t *row = lv_event_get_target(e);
289	
290	  /* Find which experiment was clicked by checking row index in parent */
291	
292	  category_t *cat = &g_phy.categories[cat_idx];
293	  int exp_idx = -1;
294	  int i;
295	
296	  for (i = 0; i < cat->num_experiments; i++)
297	    {
298	      /* Get the row object from detail panel */
299	
300	      lv_obj_t *child = lv_obj_get_child(cat->detail_panel, i);
301	      if (child == row)
302	        {
303	          exp_idx = i;
304	          break;
305	        }
306	    }
307	
308	  if (exp_idx >= 0)
309	    {
310	      create_experiment_page(cat_idx, exp_idx);
311	    }
312	}
