475	static void update_fps(void)
476	{
477	  g_phy.frame_count++;
478	  uint32_t now = lv_tick_get();
479	  uint32_t elapsed = now - g_phy.last_tick;
480	
481	  if (elapsed >= 1000)
482	    {
483	      uint32_t fps = g_phy.frame_count * 1000 / elapsed;
484	      char buf[64];
485	      snprintf(buf, sizeof(buf), "FPS: %lu", (unsigned long)fps);
486	      lv_label_set_text(g_phy.fps_label, buf);
487	      g_phy.frame_count = 0;
488	      g_phy.last_tick = now;
489	    }
490	}
