546	static void nav_pop(void)
547	{
548	  if (g_nav.top <= 0)
549	    {
550	      return;
551	    }
552	
553	  lv_obj_t *current = g_nav.screens[g_nav.top];
554	  g_nav.top--;
555	  lv_obj_t *prev = g_nav.screens[g_nav.top];
556	  lv_screen_load_anim(prev, LV_SCR_LOAD_ANIM_MOVE_RIGHT, ANIM_TIME, 0,
557	                       false);
558	
559	  /* Delete current screen after animation */
560	
561	  lv_obj_delete(current);
562	}
