739	int main(int argc, FAR char *argv[])
740	{
741	  lv_nuttx_dsc_t info;
742	  lv_nuttx_result_t result;
743	
744	  if (lv_is_initialized())
745	    {
746	      LV_LOG_ERROR("LVGL already initialized! aborting.");
747	      return -1;
748	    }
749	
750	#ifdef CONFIG_BOARDCTL
751	#  ifndef CONFIG_NSH_ARCHINIT
752	  boardctl(BOARDIOC_INIT, 0);
753	#  endif
754	#endif
755	
756	  lv_init();
757	  lv_nuttx_dsc_init(&info);
758	
759	#ifdef CONFIG_LV_USE_NUTTX_LCD
760	  info.fb_path = "/dev/lcd0";
761	#endif
762	
763	#ifdef CONFIG_INPUT_TOUCHSCREEN
764	  info.input_path = "/dev/input0";
765	#endif
766	
767	  lv_nuttx_init(&info, &result);
768	
769	  if (result.disp == NULL)
770	    {
771	      LV_LOG_ERROR("Display initialization failure!");
772	      return 1;
773	    }
774	
775	  /* Dark background */
776	
777	  lv_obj_set_style_bg_color(lv_screen_active(),
778	                             lv_color_hex(0x0A0A1A), 0);
779	  lv_obj_set_style_bg_opa(lv_screen_active(), LV_OPA_100, 0);
780	
781	  /* Initialize context */
782	
783	  memset(&g_phy, 0, sizeof(g_phy));
784	  memset(&g_nav, 0, sizeof(g_nav));
785	  memset(&g_detail, 0, sizeof(g_detail));
786	  g_phy.last_tick = lv_tick_get();
787	  g_nav.top = -1;
788	
789	  /* Build UI */
790	
791	  create_header();
792	  create_menu();
793	  create_status_bar();
794	
795	  /* Push main screen to navigation stack */
796	
797	  g_nav.screens[++g_nav.top] = lv_screen_active();
798	
799	  /* Animation timer */
800	
801	  lv_timer_create(main_timer_cb, 100, NULL);
802	
803	  /* Main loop */
804	
805	  while (1)
806	    {
807	      uint32_t idle = lv_timer_handler();
808	      idle = idle ? idle : 1;
809	      usleep(idle * 1000);
810	    }
811	
812	  return 0;
813	}
